import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int P = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        int[] parent = new int[P + 1];
        int[] rank = new int[P + 1];
        for (int i = 1; i <= P; i++) {
            parent[i] = i;
            rank[i] = 1;
        }

        // find function with path compression
        java.util.function.Function<Integer, Integer> findp = new java.util.function.Function<Integer, Integer>() {
            public Integer apply(Integer x) {
                if (parent[x] != x) {
                    parent[x] = apply(parent[x]);
                }
                return parent[x];
            }
        };

        // merge function
        java.util.function.BiConsumer<Integer, Integer> merge = (a, b) -> {
            if (rank[a] >= rank[b]) {
                parent[b] = a;
                rank[a]++;
            } else {
                parent[a] = b;
                rank[b]++;
            }
        };

        for (int i = 1; i <= P; i++) {
            int val = (int)((long)K * i % P);
            int pa = findp.apply(i);
            int pb = findp.apply(val);
            if (pa != pb) {
                merge.accept(pa, pb);
            }
        }

        Set<Integer> group_ids = new HashSet<>();
        for (int i = 1; i <= P; i++) {
            group_ids.add(findp.apply(i));
        }

        final long MOD = 1000000007L;

        // fast exponentiation
        java.util.function.BiFunction<Long, Long, Long> fast_pow = (base, exp) -> {
            long res = 1;
            long b = base;
            long e = exp;
            while (e > 0) {
                if ((e & 1) == 1) {
                    res = (res * b) % MOD;
                }
                b = (b * b) % MOD;
                e >>= 1;
            }
            return res;
        };

        long ways;
        if (K == 0) {
            ways = fast_pow.apply((long) P, (long) P - 1);
        } else if (K == 1) {
            ways = fast_pow.apply((long) P, (long) P);
        } else {
            ways = fast_pow.apply((long) P, (long) group_ids.size());
        }

        System.out.println(ways);
    }
}
